export interface Autopay {
  id: string;
  memberId: string;
  merchant: string;
  amount: number;
  /** 매월 출금일(1~28) */
  billingDay: number;
  /** 가맹점 출금 배치 시각 "HH:MM" */
  billingTime: string;
